#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=4
CODEX=/usr/bin/codex
CODEX_HOME=/var/lib/voice-codex/.codex
CODEX_BROWSER_STATE=/var/lib/voice-codex/browser/keeplore.json
PUBLISHER_SOCKET=/run/voice-agent-keeplore-publisher/publisher.sock

if [[ ! -e /opt/voice-agent/current ]]; then
  warn "Run this wizard on the Agent Host after promoting the reviewed Voice Agent release."
  exit 1
fi
RELEASE_ROOT=
if ! RELEASE_ROOT=$(readlink -f /opt/voice-agent/current) || \
  [[ ! $RELEASE_ROOT =~ ^/opt/voice-agent/releases/[0-9a-f]{40}$ ]] || \
  [[ ! -d $RELEASE_ROOT ]]; then
  warn "The active Voice Agent release path is invalid."
  exit 1
fi
PLAYWRIGHT="$RELEASE_ROOT/node_modules/.bin/playwright"

banner "Restricted Codex Keeplore Button Trial"

stage "Verify the restricted Subagent boundary"
say "The reviewed release owns provisioning; this stage verifies it without broadening authority."
sudo systemctl is-active --quiet voice-agent-subagent.service
sudo systemctl is-active --quiet voice-agent-keeplore-publisher.service
id voice-codex >/dev/null
getent group voice-subagent-client >/dev/null
sudo test "$(sudo stat -c %U /var/lib/voice-codex)" = voice-codex
sudo test "$(sudo stat -c %a /var/lib/voice-codex)" = 700
sudo test "$(sudo stat -c %U /var/lib/voice-agent-worktrees/keeplore)" = voice-codex
sudo systemd-analyze security voice-agent-subagent.service \
  voice-agent-keeplore-publisher.service --no-pager || true
step "Confirm the Subagent has no sudo capabilities, Docker socket, production directory, production secret source, or Operations Broker access, and that only the pinned publisher holds App publication authority."
pause "Review the boundary report, then press Enter."

stage "Enroll Codex and verify App publication"
say "Only the eligible Codex subscription belongs to voice-codex. GitHub publication uses the reviewed root-owned Keeplore App without a user login."
note "The model permission profile cannot read the Codex or browser stores or reach the typed publisher socket."
if ! sudo test -x "$CODEX"; then
  warn "The reviewed Codex CLI is unavailable at $CODEX."
  exit 1
fi
if ! sudo test "$(sudo cat /proc/sys/kernel/apparmor_restrict_unprivileged_userns)" = 1 || \
  ! sudo grep -q '^bwrap (enforce)$' \
    /sys/kernel/security/apparmor/profiles || \
  ! sudo grep -q '^unpriv_bwrap (enforce)$' \
    /sys/kernel/security/apparmor/profiles; then
  warn "The Bubblewrap AppArmor profile is unavailable; run the attended deployment-authority upgrade from this reviewed Release."
  exit 1
fi
if ! sudo -u voice-codex env -i \
  CODEX_HOME="$CODEX_HOME" HOME=/var/lib/voice-codex \
  PATH=/usr/local/bin:/usr/bin:/bin \
  "$CODEX" login status >/dev/null 2>&1; then
  step "Complete the device flow using the separate eligible Codex subscription designated for this restricted identity."
  sudo -u voice-codex env -i \
    CODEX_HOME="$CODEX_HOME" HOME=/var/lib/voice-codex \
    PATH=/usr/local/bin:/usr/bin:/bin \
    "$CODEX" login --device-auth
fi
if sudo test -e /var/lib/voice-codex/.config/gh/hosts.yml; then
  confirm "Remove the obsolete dedicated-user GitHub login from voice-codex?" || exit 1
  sudo rm -f -- /var/lib/voice-codex/.config/gh/hosts.yml
fi
sudo test ! -e /var/lib/voice-codex/.config/gh/hosts.yml
sudo test "$(sudo stat -c %U /etc/voice-agent/keeplore-github-app.conf)" = root
sudo test "$(sudo stat -c %U /etc/voice-agent/keeplore-github-app-private-key.pem)" = root
sudo -u voice-codex test ! -r /etc/voice-agent/keeplore-github-app-private-key.pem
sudo systemctl start keeplore-repository-policy.service
sudo -u voice-codex -g voice-subagent-client /usr/bin/curl \
  --fail --silent --show-error --max-time 5 \
  --unix-socket "$PUBLISHER_SOCKET" http://localhost/healthz >/dev/null
say "Proving the installed Codex supports the custom permission profile and that model commands cannot read the subscription credential or reach publication authority."
if ! sudo -u voice-codex env -i \
  CODEX_HOME="$CODEX_HOME" PUBLISHER_SOCKET="$PUBLISHER_SOCKET" \
  HOME=/var/lib/voice-codex PATH=/usr/local/bin:/usr/bin:/bin \
  "$CODEX" sandbox --permission-profile keeplore-enrollment-check \
  --cd "$RELEASE_ROOT" \
  --config 'permissions.keeplore-enrollment-check.filesystem={":minimal" = "read", ":workspace_roots" = {"apps/worker/src/keeplore-codex-executor.ts" = "read"}}' \
  --config permissions.keeplore-enrollment-check.network.enabled=false -- \
  /bin/sh -c 'test ! -r "$CODEX_HOME/auth.json" && test ! -S "$PUBLISHER_SOCKET"'; then
  warn "The reviewed Codex enrollment sandbox failed its credential-isolation proof."
  exit 1
fi
SUBAGENT_NAMESPACES=$(sudo systemctl show voice-agent-subagent.service \
  --property=RestrictNamespaces --value)
say "Probing the model workspace sandbox under the Subagent unit's own namespace restriction; an attended shell can start Bubblewrap where the service cannot."
if ! sudo systemd-run --quiet --pipe --wait --collect \
  --unit=voice-agent-keeplore-model-sandbox-probe \
  --property=User=voice-codex --property=Group=voice-subagent-client \
  --property="RestrictNamespaces=$SUBAGENT_NAMESPACES" \
  --setenv=CODEX_HOME="$CODEX_HOME" --setenv=HOME=/var/lib/voice-codex \
  --setenv=LANG=C.UTF-8 --setenv=PATH=/usr/local/bin:/usr/bin:/bin \
  --setenv=TMPDIR=/var/lib/voice-codex/tmp \
  /usr/bin/node --experimental-strip-types \
  "$RELEASE_ROOT/apps/worker/src/keeplore-model-sandbox-probe.ts"; then
  warn "The reviewed Codex model workspace sandbox failed to initialize under the Subagent unit restrictions."
  exit 1
fi
note "The publisher will refuse stale App assessment or owner bypass attestation. If publication is refused, refresh repository-policy collection and record a new owner attestation before retrying."

stage "Enroll the authenticated Keeplore browser session"
say "The visual check uses its own Keeplore session state; it receives no server, database, SSH, or deployment credential."
sudo test -x "$PLAYWRIGHT"
sudo install -d -o voice-codex -g voice-codex -m 0700 \
  /var/lib/voice-codex/browser
sudo -u voice-codex env \
  HOME=/var/lib/voice-codex \
  PLAYWRIGHT_BROWSERS_PATH=/var/lib/voice-codex/.cache/ms-playwright \
  "$PLAYWRIGHT" install chromium
step "Run this stage from a host desktop or an SSH session with trusted display forwarding. Sign into Keeplore in the opened browser, then close it to save the session."
confirm "Open the Keeplore authentication browser now?" || exit 1
if [[ -z ${DISPLAY:-} ]]; then
  warn "No graphical display is forwarded. Reconnect with trusted X11 forwarding before opening the Keeplore browser."
  exit 1
fi
CODEX_XAUTHORITY=$(sudo -u voice-codex /usr/bin/mktemp \
  /var/lib/voice-codex/run/keeplore-xauthority.XXXXXX)
if [[ ! $CODEX_XAUTHORITY =~ ^/var/lib/voice-codex/run/keeplore-xauthority\.[A-Za-z0-9]+$ ]]; then
  warn "The temporary Keeplore display credential escaped its private directory."
  exit 1
fi
cleanup_xauthority() {
  sudo -u voice-codex /usr/bin/rm -f -- "$CODEX_XAUTHORITY"
}
trap cleanup_xauthority EXIT
if ! /usr/bin/xauth nlist "$DISPLAY" \
  | sudo -u voice-codex env XAUTHORITY="$CODEX_XAUTHORITY" \
    /usr/bin/xauth nmerge -; then
  warn "The forwarded display credential could not be transferred to the fixed browser runner."
  exit 1
fi
if ! sudo -u voice-codex env \
  DISPLAY="$DISPLAY" XAUTHORITY="$CODEX_XAUTHORITY" \
  HOME=/var/lib/voice-codex /usr/bin/xdpyinfo >/dev/null; then
  warn "The restricted browser runner cannot reach the forwarded display."
  exit 1
fi
sudo -u voice-codex env \
  DISPLAY="$DISPLAY" XAUTHORITY="$CODEX_XAUTHORITY" \
  HOME=/var/lib/voice-codex \
  PLAYWRIGHT_BROWSERS_PATH=/var/lib/voice-codex/.cache/ms-playwright \
  "$PLAYWRIGHT" open --save-storage "$CODEX_BROWSER_STATE" \
  https://keeplore.app
cleanup_xauthority
sudo test ! -e "$CODEX_XAUTHORITY"
trap - EXIT
CODEX_XAUTHORITY=
sudo test -s "$CODEX_BROWSER_STATE"
sudo chmod 0600 "$CODEX_BROWSER_STATE"
if ! sudo -u voice-codex env -i \
  CODEX_BROWSER_STATE="$CODEX_BROWSER_STATE" CODEX_HOME="$CODEX_HOME" \
  HOME=/var/lib/voice-codex PATH=/usr/local/bin:/usr/bin:/bin \
  "$CODEX" sandbox --permission-profile keeplore-browser-check \
  --cd "$RELEASE_ROOT" \
  --config 'permissions.keeplore-browser-check.filesystem={":minimal" = "read", ":workspace_roots" = {"apps/worker/src/keeplore-codex-executor.ts" = "read"}}' \
  --config permissions.keeplore-browser-check.network.enabled=false -- \
  /bin/sh -c 'test ! -r "$CODEX_BROWSER_STATE"'; then
  warn "The reviewed Codex browser-state isolation proof failed."
  exit 1
fi
note "The browser state is readable only by trusted voice-codex runner code and is passed to neither the Voice Agent nor model-generated commands."

stage "Pin the source revision and run the telephone trial"
SOURCE_MIRROR=/var/lib/keeplore-source/repository.git
sudo test -d "$SOURCE_MIRROR"
DEFAULT_SOURCE_COMMIT=$(sudo git --git-dir="$SOURCE_MIRROR" \
  rev-parse refs/remotes/origin/main)
ask KEEPLORE_SOURCE_COMMIT \
  "40-character registered Keeplore source commit [$DEFAULT_SOURCE_COMMIT]"
KEEPLORE_SOURCE_COMMIT=${KEEPLORE_SOURCE_COMMIT:-$DEFAULT_SOURCE_COMMIT}
if [[ ! $KEEPLORE_SOURCE_COMMIT =~ ^[0-9a-f]{40}$ ]] || \
  ! sudo git --git-dir="$SOURCE_MIRROR" cat-file -e \
    "$KEEPLORE_SOURCE_COMMIT^{commit}"; then
  warn "Choose an exact commit already present in the root-owned Keeplore source mirror."
  exit 1
fi
if ! sudo -u voice-codex -g voice-subagent-client /usr/bin/git \
  --git-dir="$SOURCE_MIRROR" cat-file -e \
  "$KEEPLORE_SOURCE_COMMIT^{commit}"; then
  warn "The restricted Subagent cannot read the registered Keeplore source commit."
  exit 1
fi
delegation_environment=$(mktemp)
printf 'KEEPLORE_SOURCE_COMMIT=%s\n' "$KEEPLORE_SOURCE_COMMIT" \
  > "$delegation_environment"
sudo install -o root -g root -m 0644 "$delegation_environment" \
  /etc/voice-agent/keeplore-delegation.env
rm -f -- "$delegation_environment"
sudo systemctl restart voice-agent-keeplore-publisher.service \
  voice-agent-subagent.service voice-agent-worker.service
step "Call the registered Voice Agent telephone and say: Make the Get Rid Of button match Remove in Keeplore's table view."
step "Confirm only after the exact readback names Keeplore production, table-only scope, visual measurements, and unchanged card view."
step "Say Stop at any point to preserve completed commits and unfinished work without reset, stash, or deletion."
pause "Press Enter after the background Delegation reaches a terminal state."
sudo -u voice-agent env \
  VOICE_AGENT_DATABASE_PATH=/var/lib/voice-agent/voice-agent.sqlite \
  /usr/bin/node --experimental-strip-types \
  "$RELEASE_ROOT/apps/worker/src/keeplore-delegation-inspect.ts"
step "Open the reported pull request and inspect its branch, commits, changed file, automated check, authenticated desktop/mobile screenshots, computed styles, card-view proof, and risks. Do not merge until you accept it as the Human Merge."
pause "Press Enter after reviewing the structured Delegation Result."

finish
